//! 🎟️ Real original registry stages keep their caller output before independently refused publication.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
thread_local!{static REFUSE_HANDOFF:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};static REFUSE_PUBLICATION:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
pub(super) fn narrow_handoff(cx:&mut StepContext<'_>){if REFUSE_HANDOFF.with(|flag|flag.replace(false)){semio_framework_job_context::testkit::refuse_current_retained_receipt(cx);}}
pub(super) fn narrow_publication(cx:&mut StepContext<'_>){if REFUSE_PUBLICATION.with(|flag|flag.replace(false)){semio_framework_job_context::testkit::refuse_current_retained_receipt(cx);}}
static PAGES:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::new();
static BYTES:OriginalJobBytesReturnRegistry<1>=OriginalJobBytesReturnRegistry::with_return_wake(wake);
fn wake(){}
#[test]
fn genuine_registry_admission_preserves_partial_and_refused_ready_output_under_quantum_one(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let s=&row["source"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(7541),Generation(1),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());caller.birth_returns(bank);let mut page=None;let mut bytes=None;
 for denied in [RetainedCloneGrant{maximum_items:0,..q},RetainedCloneGrant{maximum_depth:0,..q}]{caller.turn(denied,|cx|{let work=cx.original_work_units_spent();let(result,heap)=observe(||PAGES.reserve(&mut page,cx));assert!(!result?);assert!(page.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();}
 for stage in 0..row["stages"].as_array().unwrap().len(){caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();if stage+1==row["stages"].as_array().unwrap().len(){REFUSE_HANDOFF.with(|flag|flag.set(true));}let(result,heap)=observe(||semio_framework_job_context::testkit::with_retained_receipt_policy(cx,|cx|PAGES.reserve(&mut page,cx)));let after=cx.retained_progress();assert_eq!(heap,(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));assert_eq!(cx.original_work_units_spent()-work,row["actualWork"][stage].as_u64().unwrap()as u128);assert_eq!(cx.retained_progress().copied_items-before.copied_items,1);assert_eq!(page.is_some(),stage>0);assert_eq!(page.as_ref().is_some_and(OriginalJobPageReservation::ready),stage+1==row["stages"].as_array().unwrap().len());if stage+1==row["stages"].as_array().unwrap().len(){assert!(result.is_err());}else{assert!(!result?);}Ok(())})).unwrap();}
 caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(PAGES.reserve(&mut page,cx)?);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();drop(page.take());
 let source=caller.turn(q,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();
 for _ in 0..32{if !PAGES.retains_source(source){break;}caller.turn(q,|cx|PAGES.close_returned_step(cx).map(|_|())).unwrap();}assert!(!PAGES.retains_source(source));
 caller.turn(q,|cx|{assert!(!BYTES.reserve(&mut bytes,cx)?);assert!(bytes.is_some());assert!(!bytes.as_ref().unwrap().ready());Ok(())}).unwrap();drop(bytes.take());for _ in 0..32{if !BYTES.retains_source(source){break;}caller.turn(q,|cx|BYTES.close_returned_step(cx).map(|_|())).unwrap();}assert!(!BYTES.retains_source(source));caller.retire(bank);
}

#[path="../../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
static PUBLICATION:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::new();
#[test]
fn genuine_original_page_publication_keeps_the_exact_output_before_receipt_refusal(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../📖️source/📦️page-transfer/case.json")).unwrap();assert!(law["refusedPostingKeepsOutput"].as_bool().unwrap());let reference=&law["cases"][0]["pages"][0];let bytes=serde_json::to_vec(reference).unwrap();
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(7603),Generation(5),JobPayloadStream::CommitOutput,&bytes,JOB_PAYLOAD_PAGE_BYTES);original.birth_returns();original.birth_returns();let pointer=original.builder.published().unwrap().single_page().unwrap().as_ptr();let q=RetainedCloneGrant{maximum_copy_bytes:0,..original_payload::SOURCE};let mut reservation=None;
 let mut reserve_turns=0;for _ in 0..64{reserve_turns+=1;let n=reserve_turns;if original.caller.turn(if n==1{q}else{original_payload::SOURCE},|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|PUBLICATION.reserve(&mut reservation,cx))).unwrap(){break}}assert!(reservation.as_ref().unwrap().ready());let mut reservation=reservation.take().unwrap();let source=original.caller.turn(q,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();let mut output=None;
 let mut spent=None;let(result,heap)=observe(||original.original_turn(q,|builder,cx|{let work=cx.original_work_units_spent();REFUSE_PUBLICATION.with(|flag|flag.set(true));let result=semio_framework_job_context::testkit::with_retained_receipt_policy(cx,|cx|builder.supply_last_page(&mut reservation,&mut output,cx));spent=Some(cx.original_work_units_spent()-work);result}));assert!(result.is_err());assert_eq!(spent,Some(1));assert_eq!(heap,(0,0));assert_eq!(original.caller.receipt().copied_items,1);assert_eq!(original.caller.receipt().copied_bytes,0);assert_eq!(output.as_ref().unwrap().bytes().as_ptr(),pointer);assert_eq!(serde_json::from_slice::<serde_json::Value>(output.as_ref().unwrap().bytes()).unwrap(),*reference);assert_eq!(output.as_ref().unwrap().source_identity(),source);
 original.original_turn(q,|builder,cx|{let work=cx.original_work_units_spent();let p=cx.retained_progress();assert!(builder.supply_last_page(&mut reservation,&mut output,cx)?);assert_eq!(cx.original_work_units_spent(),work);assert_eq!(cx.retained_progress(),p);Ok(())}).unwrap();original.caller.cancel().cancel_now();let(_,heap)=observe(||drop(output.take()));assert_eq!(heap,(0,0));drop(reservation);
 for _ in 0..64{if !PUBLICATION.retains_source(source){break}original.original_turn(original_payload::SOURCE,|_,cx|PUBLICATION.close_returned_step(cx)).unwrap();}assert!(!PUBLICATION.retains_source(source));original.close();let(_,heap)=observe(||drop(original));assert_eq!(heap,(0,0));
}
